class foxglove_msgs__msg__CompressedVideo(Message):
    msg_name = "foxglove_msgs/msg/CompressedVideo"
    schema = '# foxglove_msgs/msg/CompressedVideo\n# A single frame of a compressed video bitstream\n\n# Generated by https://github.com/foxglove/foxglove-sdk\n\n# Timestamp of video frame\nbuiltin_interfaces/Time timestamp\n\n# Frame of reference for the video.\n# \n# The origin of the frame is the optical center of the camera. +x points to the right in the video, +y points down, and +z points into the plane of the video.\nstring frame_id\n\n# Compressed video frame data.\n# \n# For packet-based video codecs this data must begin and end on packet boundaries (no partial packets), and must contain enough video packets to decode exactly one image (either a keyframe or delta frame). Note: Foxglove does not support video streams that include B frames because they require lookahead.\n# \n# Specifically, the requirements for different `format` values are:\n# \n# - `h264`\n#   - Use Annex B formatted data\n#   - Each CompressedVideo message should contain enough NAL units to decode exactly one video frame\n#   - Each message containing a key frame (IDR) must also include a SPS NAL unit\n# \n# - `h265` (HEVC)\n#   - Use Annex B formatted data\n#   - Each CompressedVideo message should contain enough NAL units to decode exactly one video frame\n#   - Each message containing a key frame (IRAP) must also include relevant VPS/SPS/PPS NAL units\n# \n# - `vp9`\n#   - Each CompressedVideo message should contain exactly one video frame\n# \n# - `av1`\n#   - Use the "Low overhead bitstream format" (section 5.2)\n#   - Each CompressedVideo message should contain enough OBUs to decode exactly one video frame\n#   - Each message containing a key frame must also include a Sequence Header OBU\nuint8[] data\n\n# Video format.\n# \n# Supported values: `h264`, `h265`, `vp9`, `av1`.\n# \n# Note: compressed video support is subject to hardware limitations and patent licensing, so not all encodings may be supported on all platforms. See more about [H.265 support](https://caniuse.com/hevc), [VP9 support](https://caniuse.com/webm), and [AV1 support](https://caniuse.com/av1).\nstring format\n================================================================================\nMSG: builtin_interfaces/Time\n# This message communicates ROS Time defined here:\n# https://design.ros2.org/articles/clock_and_time.html\n\n# The seconds component, valid over all int32 values.\nint32 sec\n\n# The nanoseconds component, valid in the range [0, 1e9), to be added to the seconds component. \n# e.g.\n# The time -1.7 seconds is represented as {sec: -2, nanosec: 3e8}\n# The time 1.7 seconds is represented as {sec: 1, nanosec: 7e8}\nuint32 nanosec\n'
    _fields = (
        ("timestamp", "builtin_interfaces/msg/Time", False, None, False, None, None),
        ("frame_id", "string", False, None, False, None, None),
        ("data", "uint8", True, None, False, None, None),
        ("format", "string", False, None, False, None, None),
    )
