    schema = "std_msgs/Header header\nvision_msgs/BoundingBox2D[] boxes\n================================================================================\nMSG: builtin_interfaces/Time\n# This message communicates ROS Time defined here:\n# https://design.ros2.org/articles/clock_and_time.html\n\n# The seconds component, valid over all int32 values.\nint32 sec\n\n# The nanoseconds component, valid in the range [0, 1e9), to be added to the seconds component. \n# e.g.\n# The time -1.7 seconds is represented as {sec: -2, nanosec: 3e8}\n# The time 1.7 seconds is represented as {sec: 1, nanosec: 7e8}\nuint32 nanosec\n================================================================================\nMSG: std_msgs/Header\n# Standard metadata for higher-level stamped data types.\n# This is generally used to communicate timestamped data\n# in a particular coordinate frame.\n\n# Two-integer timestamp that is expressed as seconds and nanoseconds.\nbuiltin_interfaces/Time stamp\n\n# Transform frame with which this data is associated.\nstring frame_id\n================================================================================\nMSG: vision_msgs/BoundingBox2D\n# A 2D bounding box that can be rotated about its center.\n# All dimensions are in pixels, but represented using floating-point\n#   values to allow sub-pixel precision. If an exact pixel crop is required\n#   for a rotated bounding box, it can be calculated using Bresenham's line\n#   algorithm.\n\n# The 2D position (in pixels) and orientation of the bounding box center.\nvision_msgs/Pose2D center\n\n# The total size (in pixels) of the bounding box surrounding the object relative\n#   to the pose of its center.\nfloat64 size_x\nfloat64 size_y\n================================================================================\nMSG: vision_msgs/Point2D\n# Represents a 2D point in pixel coordinates.\n# XY matches the sensor_msgs/Image convention: X is positive right and Y is positive down.\n\nfloat64 x\nfloat64 y\n================================================================================\nMSG: vision_msgs/Pose2D\n# Represents a 2D pose (coordinates and a radian rotation). Rotation is positive counterclockwise.\n\nvision_msgs/Point2D position\nfloat64 theta\n"
    _fields = (
        ("header", "std_msgs/msg/Header", False, None, False, None, None),
        ("boxes", "vision_msgs/msg/BoundingBox2D", True, None, False, None, None),
    )
    header: std_msgs__msg__Header
    boxes: Sequence


